:root {
  --paper: #fffdf7;
  --ink: #26364a;
  --muted: #718093;
  --line: #d9e0e6;
  --blue: #3e7cb1;
  --blue-pale: #e7f1f8;
  --coral: #d96855;
}

* {
  box-sizing: border-box;
}

.ink-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-header {
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.eyebrow,
.card-title,
.request-name,
.source-note {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.card-title {
  margin-top: 3px;
  font-size: 21px;
  line-height: 1.1;
}

.status-badge {
  padding: 5px 9px;
  color: var(--blue);
  background: var(--blue-pale);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.request-body {
  display: grid;
  grid-template-columns: 128px 1fr;
  gap: 18px;
  padding: 16px 18px;
}

.ink-swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 0;
  min-height: 108px;
  background: var(--blue-pale);
  border-radius: 12px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.bottle-mark {
  width: 39px;
  height: 48px;
  position: relative;
  background: var(--blue);
  border-radius: 7px 7px 12px 12px;
}

.bottle-mark::before {
  content: "";
  position: absolute;
  width: 21px;
  height: 9px;
  top: -7px;
  left: 9px;
  background: var(--ink);
  border-radius: 3px 3px 0 0;
}

.bottle-mark::after {
  content: "";
  position: absolute;
  width: 23px;
  height: 12px;
  left: 8px;
  bottom: 8px;
  background: var(--paper);
  border-radius: 3px;
}

.details-panel {
  padding: 2px 0;
}

.request-name {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.25;
}

.metadata {
  display: grid;
  gap: 6px;
  margin: 11px 0 0;
}

.metadata-row {
  display: flex;
  justify-content: space-between;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}

.metadata dt {
  color: var(--muted);
}

.metadata dd {
  margin: 0;
  font-weight: 700;
}

.card-footer {
  padding: 11px 18px;
  background: var(--blue-pale);
}

.source-note {
  color: var(--muted);
  font-size: 11px;
}

.confirm-button {
  padding: 8px 12px;
  color: var(--paper);
  background: var(--coral);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}
